package com.bank.directory.service;

import com.bank.directory.model.Employee;
import java.util.List;
import java.util.logging.Logger;
import java.util.stream.Collectors;

public class DirectoryService {
    private static final Logger log = Logger.getLogger(DirectoryService.class.getName());

    public List<Employee> namesStartingWith(List<Employee> employees, String prefix) {
        log.info(() -> "Filtering names starting with '" + prefix + "'");
        return employees.stream()
                // Null guard first → short-circuit avoids NPE on null names.
                .filter(e -> e.getName() != null && e.getName().startsWith(prefix))
                .collect(Collectors.toList());
    }
}
