package com.bank.directory;

import com.bank.directory.model.Employee;
import com.bank.directory.service.DirectoryService;
import java.util.Arrays;
import java.util.List;
import java.util.logging.Logger;

public class Main {
    private static final Logger log = Logger.getLogger(Main.class.getName());

    public static void main(String[] args) {
        List<Employee> staff = Arrays.asList(
            new Employee("Amit",  "IT"),
            new Employee("Anita", "HR"),
            new Employee("Rajesh","Sales"),
            new Employee(null,    "Ops"),
            new Employee("Priya", "Sales")
        );

        new DirectoryService().namesStartingWith(staff, "A")
            .forEach(e -> log.info(() -> "A-section: " + e));
    }
}
